def execute_sql(project_id, connection_id, api_key, sql_text, result_format=None, max_rows=None, readonly=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0215000" if __import__("os").path.isdir("./environment_mix/0215000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _as_rows(obj):
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"]
        if isinstance(obj, list):
            return obj
        return []

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        x = s.strip()
        try:
            if x.endswith("Z"):
                x = x[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(x)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log_request(status, api_key_id=None, extra=None):
        try:
            log = _load("request_log.json")
            if not isinstance(log, list):
                log = _as_rows(log)
            row = {
                "id": "req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
                "endpoint": "execute_sql",
                "tool": "execute_sql",
                "timestamp": now_iso,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "project_id": project_id if isinstance(project_id, str) else None,
                "connection_id": connection_id if isinstance(connection_id, str) else None,
                "api_key_id": api_key_id,
            }
            if isinstance(extra, dict):
                row.update(extra)
            log.append(row)
            _save("request_log.json", log)
        except Exception:
            return

    def _sql_fingerprint(text):
        s = (text or "").strip().lower()
        s = re.sub(r"/\*.*?\*/", " ", s, flags=re.S)
        s = re.sub(r"--[^\n]*", " ", s)
        s = re.sub(r"'([^'\\]|\\.)*'", "?", s)
        s = re.sub(r'"([^"\\]|\\.)*"', "?", s)
        s = re.sub(r"\b\d+(\.\d+)?\b", "?", s)
        s = re.sub(r"\s+", " ", s).strip()
        # stable short fingerprint
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _statement_type(sql):
        s = (sql or "").strip().lower()
        s = re.sub(r"/\*.*?\*/", " ", s, flags=re.S).strip()
        s = re.sub(r"^\s*(--[^\n]*\n\s*)+", "", s)
        head = re.split(r"\s+", s, maxsplit=1)[0] if s else ""
        if head in ("select", "with"):
            return "select"
        if head == "explain":
            return "explain"
        if head in ("show", "describe", "desc"):
            return "show"
        if head in ("insert", "update", "delete", "replace", "merge"):
            return "dml"
        if head in ("create", "alter", "drop", "truncate", "rename"):
            return "ddl"
        return "other"

    def _gen_id(prefix):
        # 18+ chars, uppercase, matches pattern [0-9A-Z]{18,}
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        b = os.urandom(14)
        s = "".join(alphabet[x % len(alphabet)] for x in b)  # 14
        s += "".join(alphabet[x % len(alphabet)] for x in os.urandom(8))  # +8 => 22
        return prefix + s

    def _purge_retention(sql_execs, projects_rows):
        # hard delete older than retention_days per project
        proj_by_id = {p.get("id"): p for p in projects_rows if isinstance(p, dict)}
        kept = []
        changed = False
        for r in sql_execs:
            if not isinstance(r, dict):
                changed = True
                continue
            pid = r.get("project_id")
            p = proj_by_id.get(pid)
            if not p or not isinstance(p.get("retention_days"), int):
                kept.append(r)
                continue
            rd = p["retention_days"]
            req = _parse_dt(r.get("requested_at")) or _parse_dt(r.get("created_at"))
            if not req:
                kept.append(r)
                continue
            if req < (now - datetime.timedelta(days=rd)):
                changed = True
                continue
            kept.append(r)
        return kept, changed

    # -------- validate inputs --------
    if not isinstance(project_id, str) or not re.match(r"^adbprj_[0-9A-Z]{18,}$", project_id):
        _log_request("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id is invalid.")
    if not isinstance(connection_id, str) or not re.match(r"^adbconn_[0-9A-Z]{18,}$", connection_id):
        _log_request("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "connection_id is invalid.")
    if not isinstance(api_key, str) or not api_key.strip():
        _log_request("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "api_key is missing or invalid.")
    if not isinstance(sql_text, str) or not sql_text.strip():
        _log_request("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sql_text is required.")
    if result_format is None:
        result_format = "inline_json"
    if result_format not in ("inline_json", "external_ref", "none"):
        _log_request("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "result_format is invalid.")
    if max_rows is None:
        max_rows = 1000
    if not isinstance(max_rows, int) or max_rows < 0:
        _log_request("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "max_rows must be a non-negative integer.")
    if readonly is not None and not isinstance(readonly, bool):
        _log_request("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "readonly must be a boolean when provided.")

    # -------- load data --------
    projects = _as_rows(_load("projects.json"))
    conns = _as_rows(_load("db_connections.json"))
    keys = _as_rows(_load("api_keys.json"))
    sql_execs_raw = _load("sql_executions.json")
    sql_execs = _as_rows(sql_execs_raw)

    # retention purge (observable dynamics)
    sql_execs_new, purged = _purge_retention(sql_execs, projects)
    if purged:
        sql_execs = sql_execs_new
        _save("sql_executions.json", sql_execs)

    # -------- authenticate (match client-visible value OR id; here api_key is id) --------
    key_row = None
    for k in keys:
        if isinstance(k, dict) and (k.get("id") == api_key or k.get("key") == api_key or k.get("value") == api_key):
            key_row = k
            break
    if not key_row or key_row.get("status") != "active":
        _log_request("UNAUTHORIZED", api_key_id=key_row.get("id") if isinstance(key_row, dict) else None)
        return _err("UNAUTHORIZED", "api_key is missing or invalid.")
    api_key_id = key_row.get("id")

    # project must be active
    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not proj:
        _log_request("NOT_FOUND", api_key_id=api_key_id)
        return _err("NOT_FOUND", "project_id not found.")
    if proj.get("status") != "active":
        _log_request("UNAUTHORIZED", api_key_id=api_key_id)
        return _err("UNAUTHORIZED", "project is not active.")

    # key must belong to project (unless internal mode; none here)
    if key_row.get("project_id") != project_id:
        _log_request("UNAUTHORIZED", api_key_id=api_key_id)
        return _err("UNAUTHORIZED", "api_key is not authorized for this project.")

    # resolve connection: if key restricts, must use that; else may use provided or default? Tool provides connection_id; still enforce allowed_connection_id
    allowed_conn = key_row.get("allowed_connection_id")
    resolved_conn_id = allowed_conn or connection_id or proj.get("default_connection_id")
    if not resolved_conn_id:
        _log_request("VALIDATION_ERROR", api_key_id=api_key_id)
        return _err("VALIDATION_ERROR", "No connection_id available for this request (api_key.allowed_connection_id and project.default_connection_id are both null).")
    if allowed_conn and connection_id != allowed_conn:
        _log_request("UNAUTHORIZED", api_key_id=api_key_id)
        return _err("UNAUTHORIZED", "api_key is restricted to a different connection_id.")

    conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == resolved_conn_id), None)
    if not conn:
        _log_request("NOT_FOUND", api_key_id=api_key_id)
        return _err("NOT_FOUND", "connection_id not found.")
    if conn.get("project_id") != project_id:
        _log_request("VALIDATION_ERROR", api_key_id=api_key_id)
        return _err("VALIDATION_ERROR", "FK integrity violation: connection_id does not belong to project_id.")
    if conn.get("status") != "active":
        _log_request("UNAUTHORIZED", api_key_id=api_key_id)
        return _err("UNAUTHORIZED", "connection is not active.")
    if conn.get("engine") != "adb_mysql":
        _log_request("VALIDATION_ERROR", api_key_id=api_key_id)
        return _err("VALIDATION_ERROR", "connection engine is invalid for this service.")

    # rate limit: count executions in last 60s for api_key_id
    limit = key_row.get("rate_limit_per_minute")
    if not isinstance(limit, int) or limit < 1:
        limit = 60
    cutoff = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in sql_execs:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != api_key_id:
            continue
        dt = _parse_dt(r.get("requested_at"))
        if dt and dt >= cutoff:
            recent += 1
    if recent >= limit:
        _log_request("RATE_LIMIT", api_key_id=api_key_id, extra={"rate_limit_per_minute": limit})
        return _err("RATE_LIMIT", "Rate limit exceeded.", rate_limit_per_minute=limit)

    # readonly enforcement: request-level readonly OR key-level allow_readonly_only
    stype = _statement_type(sql_text)
    if key_row.get("allow_readonly_only") is True or readonly is True:
        if stype not in ("select", "explain", "show"):
            _log_request("UNAUTHORIZED", api_key_id=api_key_id)
            return _err("UNAUTHORIZED", "Access denied: write operations not permitted for this API key")

    # update key last_used_at on successful auth (before execution record creation is okay; but must persist)
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("api_keys.json", keys)

    # result limiting
    key_max = key_row.get("max_rows_returned")
    if not isinstance(key_max, int) or key_max < 0:
        key_max = 0
    effective_max_rows = min(max_rows, key_max) if key_max > 0 else max_rows

    fp = _sql_fingerprint(sql_text)

    # create execution row queued
    exec_id = _gen_id("adbexec_")
    execution = {
        "id": exec_id,
        "project_id": project_id,
        "connection_id": resolved_conn_id,
        "api_key_id": api_key_id,
        "tool_name": "execute_sql",
        "sql_text": sql_text,
        "sql_fingerprint": fp,
        "status": "queued",
        "statement_type": stype,
        "requested_at": now_iso,
        "started_at": None,
        "finished_at": None,
        "duration_ms": None,
        "rows_returned": None,
        "rows_affected": None,
        "result_truncated": False,
        "result_format": "none",
        "result_inline_json": None,
        "result_external_ref": None,
        "error_code": None,
        "error_message": None,
        "query_plan_text": None,
        "execution_plan_text": None,
        "runtime_stats": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    sql_execs.append(execution)
    _save("sql_executions.json", sql_execs)

    # transition queued -> running
    started = datetime.datetime.now(datetime.timezone.utc)
    started_iso = started.isoformat().replace("+00:00", "Z")
    execution["status"] = "running"
    execution["started_at"] = started_iso
    execution["updated_at"] = started_iso
    _save("sql_executions.json", sql_execs)

    # "execute" offline: synthesize plausible results deterministically from fingerprint
    # succeed unless statement disallowed already handled; mark other as succeeded with no results
    finished = datetime.datetime.now(datetime.timezone.utc)
    finished_iso = finished.isoformat().replace("+00:00", "Z")
    dur_ms = int((finished - started).total_seconds() * 1000)
    if dur_ms < 0:
        dur_ms = 0

    try:
        # Use fingerprint bytes to create stable rows; avoid raising
        digest = hashlib.sha256(fp.encode("utf-8")).digest()
        n_rows = 0
        rows = None
        rows_affected = None

        if stype in ("select", "show", "explain"):
            # generate some rows, respect effective_max_rows and absolute cap to avoid huge payloads
            base_n = (digest[0] % 250) + 1  # 1..250
            n_rows = base_n
            truncated = False
            if effective_max_rows >= 0 and n_rows > effective_max_rows:
                n_rows = effective_max_rows
                truncated = True
            # always keep inline results small-ish for offline mode
            hard_cap = 2000
            if n_rows > hard_cap:
                n_rows = hard_cap
                truncated = True

            if result_format == "inline_json":
                rows = []
                for i in range(n_rows):
                    rows.append({
                        "row": i + 1,
                        "value": int.from_bytes(digest[(i % 16): (i % 16) + 1], "big"),
                        "fingerprint": fp[:12],
                    })
                execution["result_format"] = "inline_json"
                execution["result_inline_json"] = {"columns": ["row", "value", "fingerprint"], "rows": rows}
                execution["result_external_ref"] = None
            elif result_format == "external_ref":
                execution["result_format"] = "external_ref"
                execution["result_inline_json"] = None
                execution["result_external_ref"] = f"ext://sql_results/{exec_id}"
            else:
                execution["result_format"] = "none"
                execution["result_inline_json"] = None
                execution["result_external_ref"] = None

            execution["rows_returned"] = n_rows
            execution["rows_affected"] = None
            execution["result_truncated"] = bool(truncated)
        else:
            # dml/ddl/other: no result set, pretend some affected rows
            rows_affected = (digest[1] % 50)
            execution["rows_returned"] = 0
            execution["rows_affected"] = rows_affected
            execution["result_truncated"] = False
            execution["result_format"] = "none"
            execution["result_inline_json"] = None
            execution["result_external_ref"] = None

        execution["status"] = "succeeded"
        execution["finished_at"] = finished_iso
        execution["duration_ms"] = dur_ms
        execution["updated_at"] = finished_iso
        _save("sql_executions.json", sql_execs)

        _log_request("succeeded", api_key_id=api_key_id, extra={"execution_id": exec_id})
        return {"execution": execution}
    except Exception:
        # unexpected conditions should not raise; mark failed and persist
        execution["status"] = "failed"
        execution["finished_at"] = finished_iso
        execution["duration_ms"] = dur_ms
        execution["error_code"] = "INTERNAL_ERROR"
        execution["error_message"] = "Internal error while executing SQL."
        execution["updated_at"] = finished_iso
        _save("sql_executions.json", sql_execs)
        _log_request("failed", api_key_id=api_key_id, extra={"execution_id": exec_id})
        return _err("CONFLICT", "Execution failed.", execution_id=exec_id)

def get_query_plan(project_id, connection_id, api_key, sql_text, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0215000" if __import__("os").path.isdir("./environment_mix/0215000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _as_rows(obj):
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"]
        if isinstance(obj, list):
            return obj
        return []

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        x = s.strip()
        try:
            if x.endswith("Z"):
                x = x[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(x)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log_request(status, api_key_id=None, extra=None):
        try:
            log = _load("request_log.json")
            if not isinstance(log, list):
                log = _as_rows(log)
            row = {
                "id": "req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
                "endpoint": "get_query_plan",
                "tool": "get_query_plan",
                "timestamp": now_iso,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "project_id": project_id if isinstance(project_id, str) else None,
                "connection_id": connection_id if isinstance(connection_id, str) else None,
                "api_key_id": api_key_id,
            }
            if isinstance(extra, dict):
                row.update(extra)
            log.append(row)
            _save("request_log.json", log)
        except Exception:
            return

    def _sql_fingerprint(text):
        s = (text or "").strip().lower()
        s = re.sub(r"/\*.*?\*/", " ", s, flags=re.S)
        s = re.sub(r"--[^\n]*", " ", s)
        s = re.sub(r"'([^'\\]|\\.)*'", "?", s)
        s = re.sub(r'"([^"\\]|\\.)*"', "?", s)
        s = re.sub(r"\b\d+(\.\d+)?\b", "?", s)
        s = re.sub(r"\s+", " ", s).strip()
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        b = os.urandom(22)
        s = "".join(alphabet[x % len(alphabet)] for x in b)
        return prefix + s

    def _purge_retention(sql_execs, projects_rows):
        proj_by_id = {p.get("id"): p for p in projects_rows if isinstance(p, dict)}
        kept = []
        changed = False
        for r in sql_execs:
            if not isinstance(r, dict):
                changed = True
                continue
            pid = r.get("project_id")
            p = proj_by_id.get(pid)
            if not p or not isinstance(p.get("retention_days"), int):
                kept.append(r)
                continue
            rd = p["retention_days"]
            req = _parse_dt(r.get("requested_at")) or _parse_dt(r.get("created_at"))
            if not req:
                kept.append(r)
                continue
            if req < (now - datetime.timedelta(days=rd)):
                changed = True
                continue
            kept.append(r)
        return kept, changed

    # validate
    if not isinstance(project_id, str) or not re.match(r"^adbprj_[0-9A-Z]{18,}$", project_id):
        _log_request("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id is invalid.")
    if not isinstance(connection_id, str) or not re.match(r"^adbconn_[0-9A-Z]{18,}$", connection_id):
        _log_request("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "connection_id is invalid.")
    if not isinstance(api_key, str) or not api_key.strip():
        _log_request("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "api_key is missing or invalid.")
    if not isinstance(sql_text, str) or not sql_text.strip():
        _log_request("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sql_text is required.")

    projects = _as_rows(_load("projects.json"))
    conns = _as_rows(_load("db_connections.json"))
    keys = _as_rows(_load("api_keys.json"))
    sql_execs = _as_rows(_load("sql_executions.json"))

    sql_execs_new, purged = _purge_retention(sql_execs, projects)
    if purged:
        sql_execs = sql_execs_new
        _save("sql_executions.json", sql_execs)

    key_row = next((k for k in keys if isinstance(k, dict) and (k.get("id") == api_key or k.get("key") == api_key or k.get("value") == api_key)), None)
    if not key_row or key_row.get("status") != "active":
        _log_request("UNAUTHORIZED", api_key_id=key_row.get("id") if isinstance(key_row, dict) else None)
        return _err("UNAUTHORIZED", "api_key is missing or invalid.")
    api_key_id = key_row.get("id")

    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not proj:
        _log_request("NOT_FOUND", api_key_id=api_key_id)
        return _err("NOT_FOUND", "project_id not found.")
    if proj.get("status") != "active":
        _log_request("UNAUTHORIZED", api_key_id=api_key_id)
        return _err("UNAUTHORIZED", "project is not active.")
    if key_row.get("project_id") != project_id:
        _log_request("UNAUTHORIZED", api_key_id=api_key_id)
        return _err("UNAUTHORIZED", "api_key is not authorized for this project.")

    allowed_conn = key_row.get("allowed_connection_id")
    resolved_conn_id = allowed_conn or connection_id or proj.get("default_connection_id")
    if not resolved_conn_id:
        _log_request("VALIDATION_ERROR", api_key_id=api_key_id)
        return _err("VALIDATION_ERROR", "No connection_id available for this request (api_key.allowed_connection_id and project.default_connection_id are both null).")
    if allowed_conn and connection_id != allowed_conn:
        _log_request("UNAUTHORIZED", api_key_id=api_key_id)
        return _err("UNAUTHORIZED", "api_key is restricted to a different connection_id.")

    conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == resolved_conn_id), None)
    if not conn:
        _log_request("NOT_FOUND", api_key_id=api_key_id)
        return _err("NOT_FOUND", "connection_id not found.")
    if conn.get("project_id") != project_id:
        _log_request("VALIDATION_ERROR", api_key_id=api_key_id)
        return _err("VALIDATION_ERROR", "FK integrity violation: connection_id does not belong to project_id.")
    if conn.get("status") != "active":
        _log_request("UNAUTHORIZED", api_key_id=api_key_id)
        return _err("UNAUTHORIZED", "connection is not active.")

    # rate limit
    limit = key_row.get("rate_limit_per_minute")
    if not isinstance(limit, int) or limit < 1:
        limit = 60
    cutoff = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in sql_execs:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != api_key_id:
            continue
        dt = _parse_dt(r.get("requested_at"))
        if dt and dt >= cutoff:
            recent += 1
    if recent >= limit:
        _log_request("RATE_LIMIT", api_key_id=api_key_id, extra={"rate_limit_per_minute": limit})
        return _err("RATE_LIMIT", "Rate limit exceeded.", rate_limit_per_minute=limit)

    # update key last_used_at on successful auth
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("api_keys.json", keys)

    fp = _sql_fingerprint(sql_text)

    # reuse existing within retention window if has query_plan_text
    retention_days = proj.get("retention_days") if isinstance(proj.get("retention_days"), int) else 1
    window_start = now - datetime.timedelta(days=retention_days)
    reusable = None
    for r in sql_execs:
        if not isinstance(r, dict):
            continue
        if r.get("project_id") != project_id or r.get("connection_id") != resolved_conn_id:
            continue
        if r.get("sql_fingerprint") != fp:
            continue
        created = _parse_dt(r.get("created_at")) or _parse_dt(r.get("requested_at"))
        if created and created >= window_start and r.get("query_plan_text"):
            reusable = r
            break
    if reusable:
        _log_request("succeeded", api_key_id=api_key_id, extra={"execution_id": reusable.get("id"), "reused": True})
        return {"execution": reusable, "query_plan_text": reusable.get("query_plan_text")}

    # create new sql_executions row and populate query_plan_text
    exec_id = _gen_id("adbexec_")
    plan = f"id=1; select_type=SIMPLE; table=(derived); type=range; key=idx_{fp[:8]}; rows={(int(fp[:2], 16) % 200000) + 1000}; Extra=Using where"
    row = {
        "id": exec_id,
        "project_id": project_id,
        "connection_id": resolved_conn_id,
        "api_key_id": api_key_id,
        "tool_name": "get_query_plan",
        "sql_text": sql_text,
        "sql_fingerprint": fp,
        "status": "succeeded",
        "statement_type": "explain",
        "requested_at": now_iso,
        "started_at": now_iso,
        "finished_at": now_iso,
        "duration_ms": 0,
        "rows_returned": None,
        "rows_affected": None,
        "result_truncated": False,
        "result_format": "none",
        "result_inline_json": None,
        "result_external_ref": None,
        "error_code": None,
        "error_message": None,
        "query_plan_text": plan,
        "execution_plan_text": None,
        "runtime_stats": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    sql_execs.append(row)
    _save("sql_executions.json", sql_execs)

    _log_request("succeeded", api_key_id=api_key_id, extra={"execution_id": exec_id, "reused": False})
    return {"execution": row, "query_plan_text": plan}

def get_execution_plan(project_id, execution_id, api_key, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0215000" if __import__("os").path.isdir("./environment_mix/0215000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _as_rows(obj):
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"]
        if isinstance(obj, list):
            return obj
        return []

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        x = s.strip()
        try:
            if x.endswith("Z"):
                x = x[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(x)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _log_request(status, api_key_id=None, extra=None):
        try:
            log = _load("request_log.json")
            if not isinstance(log, list):
                log = _as_rows(log)
            row = {
                "id": "req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
                "endpoint": "get_execution_plan",
                "tool": "get_execution_plan",
                "timestamp": now_iso,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "project_id": project_id if isinstance(project_id, str) else None,
                "execution_id": execution_id if isinstance(execution_id, str) else None,
                "api_key_id": api_key_id,
            }
            if isinstance(extra, dict):
                row.update(extra)
            log.append(row)
            _save("request_log.json", log)
        except Exception:
            return

    # validate
    if not isinstance(project_id, str) or not re.match(r"^adbprj_[0-9A-Z]{18,}$", project_id):
        _log_request("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id is invalid.")
    if not isinstance(execution_id, str) or not re.match(r"^adbexec_[0-9A-Z]{18,}$", execution_id):
        _log_request("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "execution_id is invalid.")
    if not isinstance(api_key, str) or not api_key.strip():
        _log_request("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "api_key is missing or invalid.")

    projects = _as_rows(_load("projects.json"))
    keys = _as_rows(_load("api_keys.json"))
    sql_execs = _as_rows(_load("sql_executions.json"))

    key_row = next((k for k in keys if isinstance(k, dict) and (k.get("id") == api_key or k.get("key") == api_key or k.get("value") == api_key)), None)
    if not key_row or key_row.get("status") != "active":
        _log_request("UNAUTHORIZED", api_key_id=key_row.get("id") if isinstance(key_row, dict) else None)
        return _err("UNAUTHORIZED", "api_key is missing or invalid.")
    api_key_id = key_row.get("id")

    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not proj:
        _log_request("NOT_FOUND", api_key_id=api_key_id)
        return _err("NOT_FOUND", "project_id not found.")
    if proj.get("status") != "active":
        _log_request("UNAUTHORIZED", api_key_id=api_key_id)
        return _err("UNAUTHORIZED", "project is not active.")
    if key_row.get("project_id") != project_id:
        _log_request("UNAUTHORIZED", api_key_id=api_key_id)
        return _err("UNAUTHORIZED", "api_key is not authorized for this project.")

    # update key last_used_at on successful auth
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("api_keys.json", keys)

    ex = next((r for r in sql_execs if isinstance(r, dict) and r.get("id") == execution_id), None)
    if not ex or ex.get("project_id") != project_id:
        _log_request("NOT_FOUND", api_key_id=api_key_id)
        return _err("NOT_FOUND", "execution_id not found in project.")

    # if execution_plan_text already present, return it
    if ex.get("execution_plan_text"):
        _log_request("succeeded", api_key_id=api_key_id)
        return {
            "execution": ex,
            "execution_plan_text": ex.get("execution_plan_text"),
            "runtime_stats": ex.get("runtime_stats"),
        }

    # otherwise, create/record execution plan text (even if not supported, per rules)
    # Only allow if not terminal? rule doesn't forbid; it says return actual plan for previously submitted query.
    # We'll record "not_supported" runtime stats if missing.
    plan_txt = "Runtime Plan: not_available; note=profiling_not_supported_offline"
    runtime_stats = {"not_supported": True, "captured_at": now_iso}

    ex["execution_plan_text"] = plan_txt
    ex["runtime_stats"] = runtime_stats
    ex["updated_at"] = now_iso
    _save("sql_executions.json", sql_execs)

    _log_request("succeeded", api_key_id=api_key_id, extra={"recorded": True})
    return {"execution": ex, "execution_plan_text": plan_txt, "runtime_stats": runtime_stats}

def get_caller_identity(api_key, **_extra):
    import json, os, datetime, time, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0215000" if __import__("os").path.isdir("./environment_mix/0215000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    projects = _load("projects.json")
    conns = _load("db_connections.json")
    keys = _load("api_keys.json")
    execs = _load("sql_executions.json")

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _record_usage(status, api_key_id=None, project_id_=None, connection_id_=None):
        try:
            execs.append({
                "id": "adbexec_LOG_" + now.strftime("%Y%m%d%H%M%S") + "_" + "".join(random.choice(string.ascii_uppercase + string.digits) for _ in range(10)),
                "project_id": project_id_ or "unknown",
                "connection_id": connection_id_ or "unknown",
                "api_key_id": api_key_id,
                "tool_name": "get_caller_identity",
                "sql_text": "__usage_log__",
                "sql_fingerprint": "__usage_log__",
                "status": status,
                "statement_type": "other",
                "requested_at": now_iso,
                "started_at": now_iso,
                "finished_at": now_iso,
                "duration_ms": int((time.time() - t0) * 1000),
                "rows_returned": 0,
                "rows_affected": 0,
                "result_truncated": False,
                "result_format": "none",
                "result_inline_json": None,
                "result_external_ref": None,
                "error_code": None,
                "error_message": None,
                "query_plan_text": None,
                "execution_plan_text": None,
                "runtime_stats": {"endpoint": "get_caller_identity", "latency_ms": int((time.time() - t0) * 1000), "usage_log": True},
                "created_at": now_iso,
                "updated_at": now_iso
            })
            _save("sql_executions.json", execs)
        except Exception:
            return

    if not isinstance(api_key, str) or not api_key.strip():
        _record_usage("failed", None, None, None)
        return _err("UNAUTHORIZED", "api_key is missing or invalid.")

    key_row = None
    for k in keys:
        if k.get("id") == api_key or k.get("key_hash") == api_key:
            key_row = k
            break
    if not key_row or key_row.get("status") != "active":
        _record_usage("failed", None, None, None)
        return _err("UNAUTHORIZED", "api_key is missing, invalid, or revoked.")

    prj = next((p for p in projects if p.get("id") == key_row.get("project_id")), None)
    if not prj:
        _record_usage("failed", key_row.get("id"), key_row.get("project_id"), None)
        return _err("NOT_FOUND", "Project not found for api_key.")
    if prj.get("status") != "active":
        _record_usage("failed", key_row.get("id"), prj.get("id"), None)
        return _err("UNAUTHORIZED", "Resolved project is not active.")

    effective_conn_id = key_row.get("allowed_connection_id") or prj.get("default_connection_id")
    if not effective_conn_id:
        _record_usage("failed", key_row.get("id"), prj.get("id"), None)
        return _err("UNAUTHORIZED", "No effective connection can be resolved for this api_key/project.")

    conn = next((c for c in conns if c.get("id") == effective_conn_id), None)
    if not conn or conn.get("project_id") != prj.get("id") or conn.get("status") != "active":
        _record_usage("failed", key_row.get("id"), prj.get("id"), effective_conn_id)
        return _err("UNAUTHORIZED", "Effective connection is not usable.")

    # Purge retention for the project (observable side effect)
    retention_days = prj.get("retention_days")
    if isinstance(retention_days, int) and retention_days >= 1:
        cutoff = now - datetime.timedelta(days=retention_days)
        execs2 = [e for e in execs if (_parse_dt(e.get("requested_at")) is None) or (_parse_dt(e.get("requested_at")) >= cutoff)]
        if len(execs2) != len(execs):
            execs = execs2
            _save("sql_executions.json", execs)

    # Rate limit consumption snapshot
    limit = key_row.get("rate_limit_per_minute")
    if not isinstance(limit, int) or limit < 1:
        limit = 60
    window_start = now - datetime.timedelta(seconds=60)
    used = 0
    for e in execs:
        if e.get("api_key_id") == key_row.get("id") and e.get("tool_name") in ("execute_sql", "get_query_plan", "get_execution_plan"):
            ra = _parse_dt(e.get("requested_at"))
            if ra and ra >= window_start and e.get("sql_text") != "__usage_log__":
                used += 1

    # Update last_used_at
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("api_keys.json", keys)

    _record_usage("succeeded", key_row.get("id"), prj.get("id"), conn.get("id"))

    scopes = ["execute_sql", "get_query_plan", "get_execution_plan"]
    if key_row.get("allow_readonly_only"):
        scopes = ["execute_sql:readonly", "get_query_plan", "get_execution_plan"]

    return {
        "identity": {
            "api_key_id": key_row.get("id"),
            "api_key_name": key_row.get("name"),
            "status": key_row.get("status"),
            "project_id": prj.get("id"),
            "allowed_connection_id": key_row.get("allowed_connection_id"),
            "allow_readonly_only": bool(key_row.get("allow_readonly_only")),
            "rate_limit_per_minute": limit,
            "max_rows_returned": key_row.get("max_rows_returned"),
            "last_used_at": key_row.get("last_used_at")
        },
        "project": {
            "id": prj.get("id"),
            "name": prj.get("name"),
            "status": prj.get("status"),
            "default_connection_id": prj.get("default_connection_id"),
            "retention_days": prj.get("retention_days")
        },
        "effective_connection": {
            "id": conn.get("id"),
            "name": conn.get("name"),
            "engine": conn.get("engine"),
            "host": conn.get("host"),
            "port": conn.get("port"),
            "database_name": conn.get("database_name"),
            "tls_mode": conn.get("tls_mode"),
            "status": conn.get("status")
        },
        "granted_scopes": scopes,
        "rate_limit": {
            "window_seconds": 60,
            "limit": limit,
            "used": used,
            "remaining": max(0, limit - used),
            "reset_at": (now.replace(microsecond=0) + datetime.timedelta(seconds=60)).isoformat() + "Z"
        }
    }

def list_sql_executions(project_id, api_key, connection_id=None, api_key_id=None, status=None, statement_type=None, tool_name=None, requested_after=None, requested_before=None, limit=None, page_token=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0215000" if __import__("os").path.isdir("./environment_mix/0215000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start_ts = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    # --- helpers ---
    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _dt_from_row(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            p = _parse_rfc3339(v)
            return p
        return None

    def _b64url_encode(b):
        return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")

    def _b64url_decode(s):
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        return base64.urlsafe_b64decode((s + pad).encode("ascii"))

    def _make_token(payload_obj):
        raw = json.dumps(payload_obj, separators=(",", ":"), sort_keys=True).encode("utf-8")
        sig = hashlib.sha256(raw).digest()
        return _b64url_encode(raw) + "." + _b64url_encode(sig)

    def _parse_token(tok):
        if tok is None:
            return None
        if not isinstance(tok, str) or "." not in tok:
            return None
        a, b = tok.split(".", 1)
        try:
            raw = _b64url_decode(a)
            sig = _b64url_decode(b)
        except Exception:
            return None
        if hashlib.sha256(raw).digest() != sig:
            return None
        try:
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return None
        return obj

    def _record_latency(status_code):
        # Best-effort observable dynamics: keep a request log if a file exists.
        # (Schema provided doesn't include one; we create/append to request_log.json to preserve dynamics.)
        try:
            log = _load("request_log.json")
            if not isinstance(log, list):
                log = []
            latency_ms = int((time.time() - start_ts) * 1000)
            log.append({
                "id": "req_" + _b64url_encode(os.urandom(9)),
                "tool": "list_sql_executions",
                "timestamp": now_iso,
                "status": status_code,
                "latency_ms": latency_ms,
                "project_id": project_id if isinstance(project_id, str) else None,
                "api_key": api_key if isinstance(api_key, str) else None,
            })
            _save("request_log.json", log)
        except Exception:
            return

    # --- validate inputs ---
    if not isinstance(project_id, str) or not re.match(r"^adbprj_[0-9A-Z]{18,}$", project_id):
        _record_latency("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid project_id.")
    if not isinstance(api_key, str) or not api_key.strip():
        _record_latency("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid api_key.")
    if connection_id is not None:
        if not isinstance(connection_id, str) or not re.match(r"^adbconn_[0-9A-Z]{18,}$", connection_id):
            _record_latency("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid connection_id.")
    if api_key_id is not None:
        if not isinstance(api_key_id, str) or not re.match(r"^adbkey_[0-9A-Z]{18,}$", api_key_id):
            _record_latency("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid api_key_id.")
    if status is not None:
        if status not in ["queued", "running", "succeeded", "failed", "cancelled"]:
            _record_latency("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status.")
    if statement_type is not None:
        if statement_type not in ["select", "insert", "update", "delete", "ddl", "explain", "show", "other"]:
            _record_latency("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid statement_type.")
    if tool_name is not None:
        if tool_name not in ["execute_sql", "get_query_plan", "get_execution_plan"]:
            _record_latency("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid tool_name.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _record_latency("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid limit; must be 1..200.")

    ra = _parse_rfc3339(requested_after)
    if requested_after is not None and ra is None:
        _record_latency("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid requested_after; must be RFC3339 date-time.")
    rb = _parse_rfc3339(requested_before)
    if requested_before is not None and rb is None:
        _record_latency("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid requested_before; must be RFC3339 date-time.")
    if ra and rb and ra > rb:
        _record_latency("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "requested_after must be <= requested_before.")

    # --- load data ---
    projects = _load("projects.json")
    conns = _load("db_connections.json")
    keys = _load("api_keys.json")
    execs = _load("sql_executions.json")

    # --- authenticate api_key (explicit parameter): match by id or by a stored client-visible value.
    # Store only has key_hash; per contract, do NOT compare plaintext api_key to key_hash.
    # We therefore accept api_key as the key id (adbkey_...) when present; otherwise cannot authenticate.
    authed_key = None
    if re.match(r"^adbkey_[0-9A-Z]{18,}$", api_key):
        for k in keys:
            if isinstance(k, dict) and k.get("id") == api_key:
                authed_key = k
                break
    if authed_key is None or authed_key.get("status") != "active":
        _record_latency("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid or revoked api_key.")

    # Authorization: key's project must match requested project
    if authed_key.get("project_id") != project_id:
        _record_latency("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "api_key is not authorized for the requested project.")

    # Project must exist; for this endpoint, description says FORBIDDEN if cannot access or project not active.
    proj = None
    for p in projects:
        if isinstance(p, dict) and p.get("id") == project_id:
            proj = p
            break
    if proj is None:
        _record_latency("NOT_FOUND")
        return _err("NOT_FOUND", "Project not found.")
    if proj.get("status") != "active":
        _record_latency("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Project is not active.")

    # Retention purge (hard-delete sql_executions older than retention_days)
    retention_days = proj.get("retention_days")
    if not isinstance(retention_days, int) or retention_days < 1 or retention_days > 3650:
        _record_latency("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Project retention_days is invalid.")
    cutoff = now - datetime.timedelta(days=retention_days)
    kept_execs = []
    changed = False
    for e in execs:
        if not isinstance(e, dict):
            changed = True
            continue
        if e.get("project_id") != project_id:
            kept_execs.append(e)
            continue
        dt = _dt_from_row(e.get("requested_at")) or _dt_from_row(e.get("created_at"))
        if dt is not None and dt < cutoff:
            changed = True
            continue
        kept_execs.append(e)
    if changed:
        execs = kept_execs
        _save("sql_executions.json", execs)

    # Rate limit enforcement (based on sql_executions rows within last 60s)
    window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for e in execs:
        if not isinstance(e, dict):
            continue
        if e.get("api_key_id") != authed_key.get("id"):
            continue
        dt = _dt_from_row(e.get("requested_at"))
        if dt is None:
            continue
        if dt >= window_start:
            recent += 1
    rl = authed_key.get("rate_limit_per_minute")
    if isinstance(rl, int) and recent >= rl:
        _record_latency("RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded for api_key.", rate_limit_per_minute=rl)

    # Successful auth => update last_used_at
    authed_key["last_used_at"] = now_iso
    authed_key["updated_at"] = now_iso
    _save("api_keys.json", keys)

    # --- filter executions ---
    filtered = []
    for e in execs:
        if not isinstance(e, dict):
            continue
        if e.get("project_id") != project_id:
            continue
        if connection_id is not None and e.get("connection_id") != connection_id:
            continue
        if api_key_id is not None and e.get("api_key_id") != api_key_id:
            continue
        if status is not None and e.get("status") != status:
            continue
        if tool_name is not None and e.get("tool_name") != tool_name:
            continue

        st = e.get("statement_type")
        if statement_type is not None:
            # Stored enum is select/explain/show/dml/ddl/other; API filter includes insert/update/delete.
            if statement_type in ["insert", "update", "delete"]:
                if st != "dml":
                    continue
            else:
                if st != statement_type:
                    continue

        dt = _dt_from_row(e.get("requested_at"))
        if ra is not None and (dt is None or dt < ra):
            continue
        if rb is not None and (dt is None or dt >= rb):
            continue
        filtered.append(e)

    # Order by requested_at desc
    def _sort_key(e):
        dt = _dt_from_row(e.get("requested_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return dt
    filtered.sort(key=_sort_key, reverse=True)

    # Pagination using page_token as cursor (requested_at, id)
    cursor_dt = None
    cursor_id = None
    if page_token is not None:
        tok = _parse_token(page_token)
        if not isinstance(tok, dict) or tok.get("v") != 1 or tok.get("tool") != "list_sql_executions" or tok.get("project_id") != project_id:
            _record_latency("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid page_token.")
        cursor_dt = _parse_rfc3339(tok.get("requested_at"))
        cursor_id = tok.get("id")
        if cursor_dt is None or not isinstance(cursor_id, str):
            _record_latency("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid page_token.")

    if cursor_dt is not None:
        sliced = []
        for e in filtered:
            dt = _dt_from_row(e.get("requested_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            eid = e.get("id")
            if dt < cursor_dt:
                sliced.append(e)
            elif dt == cursor_dt and isinstance(eid, str) and isinstance(cursor_id, str) and eid < cursor_id:
                # tie-breaker: ids descending; keep items "after" the cursor
                sliced.append(e)
        filtered = sliced

    page = filtered[:limit]
    has_more = len(filtered) > len(page)
    next_token = None
    if has_more and page:
        last = page[-1]
        next_token = _make_token({
            "v": 1,
            "tool": "list_sql_executions",
            "project_id": project_id,
            "requested_at": _iso(_dt_from_row(last.get("requested_at"))),
            "id": last.get("id")
        })

    _record_latency("OK")
    return {
        "executions": page,
        "total": len(filtered) if page_token is None else None,
        "has_more": has_more,
        "next_page_token": next_token,
    }

def get_sql_execution(project_id, execution_id, api_key, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0215000" if __import__("os").path.isdir("./environment_mix/0215000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _as_rows(obj):
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"]
        if isinstance(obj, list):
            return obj
        return []

    def _log_request(status, api_key_id=None, extra=None):
        try:
            log = _load("request_log.json")
            if not isinstance(log, list):
                log = _as_rows(log)
            row = {
                "id": "req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
                "endpoint": "get_sql_execution",
                "tool": "get_sql_execution",
                "timestamp": now_iso,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "project_id": project_id if isinstance(project_id, str) else None,
                "execution_id": execution_id if isinstance(execution_id, str) else None,
                "api_key_id": api_key_id,
            }
            if isinstance(extra, dict):
                row.update(extra)
            log.append(row)
            _save("request_log.json", log)
        except Exception:
            return

    if not isinstance(project_id, str) or not re.match(r"^adbprj_[0-9A-Z]{18,}$", project_id):
        _log_request("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id is invalid.")
    if not isinstance(execution_id, str) or not re.match(r"^adbexec_[0-9A-Z]{18,}$", execution_id):
        _log_request("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "execution_id is invalid.")
    if not isinstance(api_key, str) or not api_key.strip():
        _log_request("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "api_key is missing or invalid.")

    projects = _as_rows(_load("projects.json"))
    keys = _as_rows(_load("api_keys.json"))
    sql_execs = _as_rows(_load("sql_executions.json"))

    key_row = next((k for k in keys if isinstance(k, dict) and (k.get("id") == api_key or k.get("key") == api_key or k.get("value") == api_key)), None)
    if not key_row or key_row.get("status") != "active":
        _log_request("UNAUTHORIZED", api_key_id=key_row.get("id") if isinstance(key_row, dict) else None)
        return _err("UNAUTHORIZED", "api_key is missing or invalid.")
    api_key_id = key_row.get("id")

    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not proj:
        _log_request("NOT_FOUND", api_key_id=api_key_id)
        return _err("NOT_FOUND", "project_id not found.")
    if proj.get("status") != "active":
        _log_request("UNAUTHORIZED", api_key_id=api_key_id)
        return _err("UNAUTHORIZED", "project is not active.")
    if key_row.get("project_id") != project_id:
        _log_request("UNAUTHORIZED", api_key_id=api_key_id)
        return _err("UNAUTHORIZED", "api_key is not authorized for this project.")

    # update key last_used_at on successful auth
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("api_keys.json", keys)

    ex = next((r for r in sql_execs if isinstance(r, dict) and r.get("id") == execution_id), None)
    if not ex or ex.get("project_id") != project_id:
        _log_request("NOT_FOUND", api_key_id=api_key_id)
        return _err("NOT_FOUND", "execution_id not found in project.")

    _log_request("succeeded", api_key_id=api_key_id)
    return {"execution": ex}

def cancel_sql_execution(project_id, execution_id, api_key, reason=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0215000" if __import__("os").path.isdir("./environment_mix/0215000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _as_rows(obj):
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"]
        if isinstance(obj, list):
            return obj
        return []

    def _log_request(status, api_key_id=None, extra=None):
        try:
            log = _load("request_log.json")
            if not isinstance(log, list):
                log = _as_rows(log)
            row = {
                "id": "req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
                "endpoint": "cancel_sql_execution",
                "tool": "cancel_sql_execution",
                "timestamp": now_iso,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "project_id": project_id if isinstance(project_id, str) else None,
                "execution_id": execution_id if isinstance(execution_id, str) else None,
                "api_key_id": api_key_id,
            }
            if isinstance(extra, dict):
                row.update(extra)
            log.append(row)
            _save("request_log.json", log)
        except Exception:
            return

    # validate
    if not isinstance(project_id, str) or not re.match(r"^adbprj_[0-9A-Z]{18,}$", project_id):
        _log_request("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id is invalid.")
    if not isinstance(execution_id, str) or not re.match(r"^adbexec_[0-9A-Z]{18,}$", execution_id):
        _log_request("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "execution_id is invalid.")
    if not isinstance(api_key, str) or not api_key.strip():
        _log_request("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "api_key is missing or invalid.")
    if reason is not None and not isinstance(reason, str):
        _log_request("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "reason must be a string when provided.")

    projects = _as_rows(_load("projects.json"))
    keys = _as_rows(_load("api_keys.json"))
    sql_execs = _as_rows(_load("sql_executions.json"))

    key_row = next((k for k in keys if isinstance(k, dict) and (k.get("id") == api_key or k.get("key") == api_key or k.get("value") == api_key)), None)
    if not key_row or key_row.get("status") != "active":
        _log_request("UNAUTHORIZED", api_key_id=key_row.get("id") if isinstance(key_row, dict) else None)
        return _err("UNAUTHORIZED", "api_key is missing or invalid.")
    api_key_id = key_row.get("id")

    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not proj:
        _log_request("NOT_FOUND", api_key_id=api_key_id)
        return _err("NOT_FOUND", "project_id not found.")
    if proj.get("status") != "active":
        _log_request("UNAUTHORIZED", api_key_id=api_key_id)
        return _err("UNAUTHORIZED", "project is not active.")
    if key_row.get("project_id") != project_id:
        _log_request("UNAUTHORIZED", api_key_id=api_key_id)
        return _err("UNAUTHORIZED", "api_key is not authorized for this project.")

    # update key last_used_at on successful auth
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("api_keys.json", keys)

    ex = next((r for r in sql_execs if isinstance(r, dict) and r.get("id") == execution_id), None)
    if not ex or ex.get("project_id") != project_id:
        _log_request("NOT_FOUND", api_key_id=api_key_id)
        return _err("NOT_FOUND", "execution_id not found in project.")

    # lifecycle transitions
    status = ex.get("status")
    if status in ("succeeded", "failed", "cancelled"):
        _log_request("CONFLICT", api_key_id=api_key_id)
        return _err("CONFLICT", "Execution is already in a terminal state.", status=status)

    if status not in ("queued", "running"):
        _log_request("INVALID_TRANSITION", api_key_id=api_key_id)
        return _err("INVALID_TRANSITION", "Execution cannot be cancelled from its current state.", status=status)

    ex["status"] = "cancelled"
    ex["finished_at"] = now_iso
    ex["updated_at"] = now_iso
    if isinstance(reason, str) and reason.strip():
        ex["error_message"] = f"Cancelled by client: {reason.strip()}"
        ex["error_code"] = "CANCELLED"
    else:
        ex["error_message"] = "Cancelled by client"
        ex["error_code"] = "CANCELLED"
    # duration_ms if started_at available
    try:
        sa = ex.get("started_at")
        if isinstance(sa, str):
            sdt = None
            x = sa.strip()
            if x.endswith("Z"):
                x = x[:-1] + "+00:00"
            sdt = datetime.datetime.fromisoformat(x)
            if sdt.tzinfo is None:
                sdt = sdt.replace(tzinfo=datetime.timezone.utc)
            dur = int((now - sdt.astimezone(datetime.timezone.utc)).total_seconds() * 1000)
            if dur < 0:
                dur = 0
            ex["duration_ms"] = dur
    except Exception:
        # keep existing duration_ms if any
        pass

    _save("sql_executions.json", sql_execs)
    _log_request("succeeded", api_key_id=api_key_id, extra={"cancelled": True})
    return {"execution": ex}

def list_projects(api_key, status=None, limit=None, page_token=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0215000" if __import__("os").path.isdir("./environment_mix/0215000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start_ts = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _b64url_encode(b):
        return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")
    def _b64url_decode(s):
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        return base64.urlsafe_b64decode((s + pad).encode("ascii"))
    def _make_token(payload_obj):
        raw = json.dumps(payload_obj, separators=(",", ":"), sort_keys=True).encode("utf-8")
        sig = hashlib.sha256(raw).digest()
        return _b64url_encode(raw) + "." + _b64url_encode(sig)
    def _parse_token(tok):
        if tok is None:
            return None
        if not isinstance(tok, str) or "." not in tok:
            return None
        a, b = tok.split(".", 1)
        try:
            raw = _b64url_decode(a)
            sig = _b64url_decode(b)
        except Exception:
            return None
        if hashlib.sha256(raw).digest() != sig:
            return None
        try:
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return None
        return obj

    def _record_latency(status_code):
        try:
            log = _load("request_log.json")
            if not isinstance(log, list):
                log = []
            latency_ms = int((time.time() - start_ts) * 1000)
            log.append({
                "id": "req_" + _b64url_encode(os.urandom(9)),
                "tool": "list_projects",
                "timestamp": now_iso,
                "status": status_code,
                "latency_ms": latency_ms,
                "api_key": api_key if isinstance(api_key, str) else None,
            })
            _save("request_log.json", log)
        except Exception:
            return

    if not isinstance(api_key, str) or not api_key.strip():
        _record_latency("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid api_key.")
    if status is not None and status not in ["active", "suspended", "deleted"]:
        _record_latency("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _record_latency("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid limit; must be 1..200.")

    projects = _load("projects.json")
    keys = _load("api_keys.json")
    execs = _load("sql_executions.json")

    # authenticate by key id only (see contract)
    authed_key = None
    if re.match(r"^adbkey_[0-9A-Z]{18,}$", api_key):
        for k in keys:
            if isinstance(k, dict) and k.get("id") == api_key:
                authed_key = k
                break
    if authed_key is None or authed_key.get("status") != "active":
        _record_latency("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid or revoked api_key.")

    # rate limit enforcement (count reads too)
    window_start = now - datetime.timedelta(seconds=60)
    def _parse_rfc3339(s):
        if s is None or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None
    recent = 0
    for e in execs:
        if not isinstance(e, dict):
            continue
        if e.get("api_key_id") != authed_key.get("id"):
            continue
        dt = _parse_rfc3339(e.get("requested_at"))
        if dt is not None and dt >= window_start:
            recent += 1
    rl = authed_key.get("rate_limit_per_minute")
    if isinstance(rl, int) and recent >= rl:
        _record_latency("RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded for api_key.", rate_limit_per_minute=rl)

    # successful auth => update last_used_at
    authed_key["last_used_at"] = now_iso
    authed_key["updated_at"] = now_iso
    _save("api_keys.json", keys)

    # visibility: only the owning project for this key (no separate ACL schema provided)
    visible = []
    for p in projects:
        if not isinstance(p, dict):
            continue
        if p.get("id") != authed_key.get("project_id"):
            continue
        if status is not None and p.get("status") != status:
            continue
        visible.append(p)

    # sort by created_at desc as a reasonable default
    def _sort_key(p):
        dt = _parse_rfc3339(p.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return dt
    visible.sort(key=_sort_key, reverse=True)

    # pagination by last id (stable enough given single-project visibility)
    cursor = None
    if page_token is not None:
        tok = _parse_token(page_token)
        if not isinstance(tok, dict) or tok.get("v") != 1 or tok.get("tool") != "list_projects" or tok.get("api_key_id") != authed_key.get("id"):
            _record_latency("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid page_token.")
        cursor = tok.get("after_id")
        if cursor is not None and not isinstance(cursor, str):
            _record_latency("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid page_token.")

    if cursor is not None:
        # since list is small, filter after cursor
        visible = [p for p in visible if isinstance(p.get("id"), str) and p.get("id") < cursor]

    page = visible[:limit]
    has_more = len(visible) > len(page)
    next_token = None
    if has_more and page:
        last = page[-1]
        next_token = _make_token({"v": 1, "tool": "list_projects", "api_key_id": authed_key.get("id"), "after_id": last.get("id")})

    _record_latency("OK")
    return {
        "projects": page,
        "total": len(visible) if page_token is None else None,
        "has_more": has_more,
        "next_page_token": next_token,
    }

