        _log_request("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if page_token is not None and not isinstance(page_token, str):
        _log_request("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_token must be a string.")

    projects = _load("projects.json")
    conns = _load("db_connections.json")
    keys = _load("api_keys.json")
    execs = _load("sql_executions.json")  # for rate limit bookkeeping
    if not isinstance(projects, list):
        projects = []
    if not isinstance(conns, list):
        conns = []
    if not isinstance(keys, list):
        keys = []
    if not isinstance(execs, list):
        execs = []

    # auth
    authed_key = None
    for k in keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        if api_key == k.get("id") or api_key == k.get("name"):
            authed_key = k
            break
    if authed_key is None:
        _log_request("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "api_key is invalid or revoked.")
    api_key_id = authed_key.get("id")
    if authed_key.get("project_id") != project_id:
        _log_request("UNAUTHORIZED", api_key_id=api_key_id)
        return _err("UNAUTHORIZED", "api_key is not authorized for this project.")

    project = None
    for p in projects:
        if isinstance(p, dict) and p.get("id") == project_id:
            project = p
            break
    if project is None:
        _log_request("NOT_FOUND", api_key_id=api_key_id)
        return _err("NOT_FOUND", "Project not found.")
    if project.get("status") != "active":
        _log_request("UNAUTHORIZED", api_key_id=api_key_id)
        return _err("UNAUTHORIZED", "Project is not active.")

    # rate limit check against sql_executions within last 60 seconds (shared rule)
    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            x = s.strip()
            if x.endswith("Z"):
                x = x[:-1]
            dt = datetime.datetime.fromisoformat(x)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    rpm = authed_key.get("rate_limit_per_minute")
    if not isinstance(rpm, int) or rpm < 1:
        rpm = 60
    window_start = now - datetime.timedelta(seconds=60)
    recent = 0
    for e in execs:
        if not isinstance(e, dict):
            continue
        if e.get("api_key_id") != api_key_id:
            continue
        dt = _parse_dt(e.get("requested_at"))
        if dt is not None and dt >= window_start:
            recent += 1
    if recent >= rpm:
        _log_request("RATE_LIMIT", api_key_id=api_key_id)
        return _err("RATE_LIMIT", "Rate limit exceeded for this api_key.", rate_limit_per_minute=rpm)

    # update key last_used_at on successful auth
    for k in keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", keys)

    # filtering & pagination
    allowed_conn_id = authed_key.get("allowed_connection_id")

    filtered = []
    for c in conns:
        if not isinstance(c, dict):
            continue
        if c.get("project_id") != project_id:
            continue
        if allowed_conn_id and c.get("id") != allowed_conn_id:
            continue
        if status is not None and c.get("status") != status:
            continue
        if engine is not None:
            # map request engine to stored engine name
            wanted = "adb_mysql" if engine in ("analyticdb_mysql", "adb_mysql") else engine
            if c.get("engine") != wanted:
                continue
        filtered.append(c)

    filtered.sort(key=lambda r: (r.get("name") or "", r.get("id") or ""))

    # page_token is opaque offset as string integer
    offset = 0
    if page_token:
        try:
            offset = int(page_token)
            if offset < 0:
                raise ValueError()
        except Exception:
            _log_request("VALIDATION_ERROR", api_key_id=api_key_id)
            return _err("VALIDATION_ERROR", "page_token is invalid.")
    page = filtered[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < len(filtered)
    next_page_token = str(next_offset) if has_more else None

    _log_request("OK", api_key_id=api_key_id)
    return {
        "connections": page,
        "pagination": {
            "total": len(filtered),
            "limit": limit,
            "page_token": page_token,
            "next_page_token": next_page_token,
            "has_more": has_more,
        },
    }
